import {DYNAMICS} from './expression.js';
import {scoreTracks,SCORE_ABBREVIATIONS} from './score-order.js';
import {getInstrument,barBeats,writtenOctave,writtenClef} from './catalog.js';
import {notationVoices} from './notation.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const names=[['C',0],['C',1],['D',0],['E',-1],['E',0],['F',0],['F',1],['G',0],['A',-1],['A',0],['B',-1],['B',0]],types={w:'whole',h:'half',q:'quarter','8':'eighth','16':'16th'};
function expressionDirections(track,bar,per){
 const from=bar*per,to=from+per,direction=(beat,content,sound='')=>`<direction placement="below"><direction-type>${content}</direction-type><offset>${Math.round((beat-from)*4)}</offset>${sound}</direction>`;let xml='';
 for(const e of track.events){if(e.dynamic&&e.beat>=from&&e.beat<to)xml+=direction(e.beat,`<dynamics><${e.dynamic}/></dynamics>`,`<sound dynamics="${Math.round(DYNAMICS[e.dynamic]*100)}"/>`);
  if(e.hairpin){if(e.beat>=from&&e.beat<to)xml+=direction(e.beat,`<wedge type="${e.hairpin.type}" number="1"/>`);if(e.hairpin.endBeat>=from&&e.hairpin.endBeat<to){xml+=direction(e.hairpin.endBeat,'<wedge type="stop" number="1"/>');xml+=direction(e.hairpin.endBeat,`<dynamics><${e.hairpin.target}/></dynamics>`,`<sound dynamics="${Math.round(DYNAMICS[e.hairpin.target]*100)}"/>`);}}
 }return xml;
}
export function musicXML(p){
 p={...p,tracks:scoreTracks(p)};
 const [num,den]=p.meter.split('/').map(Number);const parts=p.tracks.map((t,idx)=>{const i=getInstrument(t.instrument);return `<score-part id="P${idx+1}"><part-name>${esc(t.name)}</part-name><part-abbreviation>${esc(t.name===i.name?(SCORE_ABBREVIATIONS[i.id]||i.short):t.name)}</part-abbreviation><score-instrument id="I${idx+1}"><instrument-name>${esc(i.name)}</instrument-name></score-instrument><midi-instrument id="I${idx+1}"><midi-channel>${i.family==='drum'?10:idx%9+1}</midi-channel><midi-program>${i.family==='marimba'?13:i.family==='vibraphone'?12:i.family==='glockenspiel'?10:i.family==='recorder'?75:i.family==='timpani'?48:1}</midi-program></midi-instrument></score-part>`}).join('');
 const body=p.tracks.map((t,idx)=>{const i=getInstrument(t.instrument),drum=i.family==='drum',octave=writtenOctave(i),lanes=notationVoices(p,t,.25,{chords:true});return `<part id="P${idx+1}">`+Array.from({length:p.bars},(_,bar)=>`<measure number="${bar+1}">${bar===0?`<attributes><divisions>4</divisions><key><fifths>${p.key==='G'?1:p.key==='F'?-1:0}</fifths></key><time><beats>${num}</beats><beat-type>${den}</beat-type></time><clef><sign>${drum?'percussion':writtenClef(i)==='bass'?'F':'G'}</sign>${drum?'':`<line>${writtenClef(i)==='bass'?4:2}</line>`}</clef>${drum?`<staff-details><staff-lines>${i.pads.length===1?1:5}</staff-lines></staff-details>`:''}${octave?`<transpose><diatonic>0</diatonic><chromatic>0</chromatic><octave-change>${-octave/12}</octave-change></transpose>`:''}</attributes><direction placement="above"><direction-type><metronome><beat-unit>quarter</beat-unit><per-minute>${p.bpm}</per-minute></metronome></direction-type><sound tempo="${p.bpm}"/></direction>${drum?`<direction placement="above"><direction-type><words>${esc(i.pads.map((pad,n)=>pad[0]+(i.pads.length>1?' = '+['bottom line','second line','middle line','fourth line','top line'][n%5]:'')).join(' · '))}</words></direction-type></direction>`:''}`:''}`+(p.sectionMarkers?.filter(mark=>mark.bar===bar).map(mark=>`<direction placement="above"><direction-type><rehearsal>${esc(mark.name)}</rehearsal></direction-type></direction>`).join('')||'')+expressionDirections(t,bar,barBeats(p))+lanes.map((lane,voice)=>`${voice?`<backup><duration>${barBeats(p)*4}</duration></backup>`:''}`+lane[bar].map(token=>{return (token.source?.chord||[token.source]).map((e,chordIndex)=>{let content='<rest/>';if(e){if(drum){const ix=i.pads.findIndex(n=>n[1]===e.note&&(n[2]||0)===(e.shift||0));const pos=i.pads.length===1?['B',4]:[['E',4],['G',4],['B',4],['D',5],['F',5]][Math.max(0,ix)%5];content=`<unpitched><display-step>${pos[0]}</display-step><display-octave>${pos[1]}</display-octave></unpitched>`;}else{const note=e.note+octave,[step,alter]=names[note%12];content=`<pitch><step>${step}</step>${alter?`<alter>${alter}</alter>`:''}<octave>${Math.floor(note/12)-1}</octave></pitch>`;}}
 const start=e&&token.beat>e.beat+1e-6,more=e&&token.beat+token.duration<e.beat+e.duration-1e-6;return `<note>${chordIndex?'<chord/>':''}${content}<duration>${Math.round(token.duration*4)}</duration>${start?'<tie type="stop"/>':''}${more?'<tie type="start"/>':''}<voice>${voice+1}</voice><type>${types[token.glyph]}</type>${token.dot?'<dot/>':''}${drum||lanes.length>1?`<stem>${voice%2?'down':'up'}</stem>`:''}${start||more||e?.articulations?.length||e?.slur||(e&&!start&&!chordIndex&&t.events.some(n=>n.slur&&Math.abs(n.slur.endBeat-token.beat)<1e-6))?`<notations>${start?'<tied type="stop"/>':''}${more?'<tied type="start"/>':''}${!start&&e?.articulations?.length?'<articulations>'+e.articulations.map(a=>'<'+(a==='breath'?'breath-mark':a)+'/>').join('')+'</articulations>':''}${!start&&e?.slur?'<slur type="start" number="1"/>':''}${(e&&!start&&!chordIndex&&t.events.some(n=>n.slur&&Math.abs(n.slur.endBeat-token.beat)<1e-6))?'<slur type="stop" number="1"/>':''}</notations>`:''}</note>`;}).join('');}).join('')).join('')+`${bar===p.bars-1?'<barline location="right"><bar-style>light-heavy</bar-style></barline>':''}</measure>`).join('')+'</part>'}).join('');
 return `<?xml version="1.0" encoding="utf-8"?>\n<!DOCTYPE score-partwise PUBLIC "-//Recordare//DTD MusicXML 4.0 Partwise//EN" "http://www.musicxml.org/dtds/partwise.dtd">\n<score-partwise version="4.0"><work><work-title>${esc(p.title)}</work-title></work><identification><creator type="composer">${esc(p.composer)}</creator><encoding><software>Mallet &amp; Measure — software by Drew Wichman</software></encoding></identification><part-list>${parts}</part-list>${body}</score-partwise>`;
}
